public final class GameModes implements Listener {
 private static final String LOBBY_REGION_ID="adminsrv";
 private final PryanikPlugin plugin;
 private final Map<String,String> worldToInstance=new HashMap<>();
 private final NamespacedKey compassKey;
 public void setCompassKey(NamespacedKey key){}
 public GameModes(PryanikPlugin plugin){this.plugin=plugin;this.compassKey=new NamespacedKey(plugin,GameModeCommand.SELECTOR);}
 private Location lobbySpawn(World w){String path="admin-worlds.lobby.spawn.";return new Location(w,plugin.getConfig().getDouble(path+"x",plugin.getConfig().getDouble("admin-worlds.lobby-spawn.x",4.449)),plugin.getConfig().getDouble(path+"y",plugin.getConfig().getDouble("admin-worlds.lobby-spawn.y",-58.0)),plugin.getConfig().getDouble(path+"z",plugin.getConfig().getDouble("admin-worlds.lobby-spawn.z",21.489)),(float)plugin.getConfig().getDouble(path+"yaw",0.0),(float)plugin.getConfig().getDouble(path+"pitch",0.0));}
 private boolean isLobbyWorld(World w){return w!=null&&"lobby".equalsIgnoreCase(w.getName());}
 public boolean isLobby(World w){World l=lobby();return w!=null&&l!=null&&w.equals(l);}
 public void configureLobbyWorld(World w){if(!isLobbyWorld(w))return;w.setTime(6000L);w.setStorm(false);w.setThundering(false);w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE,false);w.setGameRule(GameRule.DO_WEATHER_CYCLE,false);w.setGameRule(GameRule.DO_MOB_SPAWNING,plugin.getConfig().getBoolean("admin-worlds."+w.getName()+".mob-spawning",false));w.setGameRule(GameRule.SPAWN_MONSTERS,plugin.getConfig().getBoolean("admin-worlds."+w.getName()+".monster-spawning",false));w.setGameRule(GameRule.DO_PATROL_SPAWNING,false);w.setGameRule(GameRule.DO_TRADER_SPAWNING,false);w.setGameRule(GameRule.DO_INSOMNIA,false);w.setGameRule(GameRule.DO_FIRE_TICK,false);w.setGameRule(GameRule.DO_IMMEDIATE_RESPAWN,true);applyMobLimits(w);w.setSpawnLocation(lobbySpawn(w));if(!plugin.getConfig().getBoolean("admin-worlds."+w.getName()+".mob-spawning",false))for(Entity e:w.getEntities())if(e instanceof LivingEntity&&!(e instanceof Player))e.remove();}
  private void applyMobLimits(World w){String path="admin-worlds."+w.getName()+".";w.setSpawnLimit(org.bukkit.entity.SpawnCategory.MONSTER,plugin.getConfig().getInt(path+"monster-cap",-1));int passiveLimit=plugin.getConfig().getInt(path+"passive-cap",-1);for(org.bukkit.entity.SpawnCategory category:org.bukkit.entity.SpawnCategory.values())if(passive(category))w.setSpawnLimit(category,passiveLimit);}
  private boolean passive(org.bukkit.entity.SpawnCategory c){return c==org.bukkit.entity.SpawnCategory.ANIMAL||c==org.bukkit.entity.SpawnCategory.WATER_ANIMAL||c==org.bukkit.entity.SpawnCategory.WATER_AMBIENT||c==org.bukkit.entity.SpawnCategory.WATER_UNDERGROUND_CREATURE||c==org.bukkit.entity.SpawnCategory.AMBIENT||c==org.bukkit.entity.SpawnCategory.AXOLOTL;}
  @EventHandler(priority=EventPriority.HIGHEST) public void configuredMobSpawns(CreatureSpawnEvent e){World w=e.getLocation().getWorld();String p="admin-worlds."+w.getName()+".";if(!plugin.getConfig().getBoolean(p+"mob-spawning",!isLobbyWorld(w)))e.setCancelled(true);else if(e.getEntity().getSpawnCategory()==org.bukkit.entity.SpawnCategory.MONSTER&&!plugin.getConfig().getBoolean(p+"monster-spawning",!isLobbyWorld(w)))e.setCancelled(true);else if(passive(e.getEntity().getSpawnCategory())&&!plugin.getConfig().getBoolean(p+"passive-spawning",!isLobbyWorld(w)))e.setCancelled(true);else if(e.getEntity().getSpawnCategory()==org.bukkit.entity.SpawnCategory.MONSTER){int cap=plugin.getConfig().getInt(p+"monster-cap",-1);if(cap>=0&&w.getEntitiesByClass(org.bukkit.entity.Monster.class).size()>=cap)e.setCancelled(true);}else if(passive(e.getEntity().getSpawnCategory())){int cap=plugin.getConfig().getInt(p+"passive-cap",-1);if(cap>=0&&w.getEntities().stream().filter(entity->passive(entity.getType().getSpawnCategory())).count()>=cap)e.setCancelled(true);}}
  public void applyConfiguredMobSettings(World w){if(w==null)return;String p="admin-worlds."+w.getName()+".";boolean all=plugin.getConfig().getBoolean(p+"mob-spawning",!isLobbyWorld(w));boolean monsters=plugin.getConfig().getBoolean(p+"monster-spawning",!isLobbyWorld(w));boolean passive=plugin.getConfig().getBoolean(p+"passive-spawning",!isLobbyWorld(w));w.setGameRule(GameRule.DO_MOB_SPAWNING,all);w.setGameRule(GameRule.SPAWN_MONSTERS,monsters);applyMobLimits(w);if(!all||!monsters||!passive)for(Entity e:w.getEntities())if(e instanceof LivingEntity&&!(e instanceof Player)&&(!all||e.getType().getSpawnCategory()==org.bukkit.entity.SpawnCategory.MONSTER&&!monsters||this.passive(e.getType().getSpawnCategory())&&!passive))e.remove();}
 public void configureLoadedSpawnWorlds(){for(World world:Bukkit.getWorlds())if(isSpawnWorld(world))configureSpawnWorld(world);}
  private GameMode configuredGameMode(World world,GameMode fallback){String value=plugin.getConfig().getString("admin-worlds."+world.getName()+".game-mode");if(value==null)return fallback;try{return GameMode.valueOf(value.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException ex){plugin.getLogger().warning("Invalid game mode configured for world "+world.getName());return fallback;}}
  public void configureLobbyPlayer(Player p){if(!isLobbyWorld(p.getWorld()))return;p.setGameMode(configuredGameMode(p.getWorld(),GameMode.ADVENTURE));p.setInvulnerable(true);p.setFallDistance(0);p.setFireTicks(0);p.setFoodLevel(20);p.setSaturation(20F);}
 public void configureSpawnPlayer(Player p){if(!isSpawnWorld(p.getWorld()))return;if(!plugin.getConfig().contains("admin-worlds."+p.getWorld().getName()+".game-mode")||!p.isOp())p.setGameMode(configuredGameMode(p.getWorld(),GameMode.ADVENTURE));p.setInvulnerable(plugin.afk(p.getUniqueId())||plugin.van(p.getUniqueId()));p.setFallDistance(0);p.setFireTicks(0);p.setFoodLevel(20);p.setSaturation(20F);}
  public void configureAllLobbyPlayers(){World w=lobby();if(w==null)return;configureLobbyWorld(w);for(Player p:w.getPlayers()){configureLobbyPlayer(p);if(plugin.gameStateManager()!=null)plugin.gameStateManager().initialize(p,"lobby");}}
 public void protectLobbyOnce(){if(plugin.getConfig().getBoolean("lobby-protection.completed",false))return;World w=lobby();if(w==null){plugin.getLogger().severe("Cannot create lobby region: lobby not loaded.");return;}RegionManager m=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w));if(m==null){plugin.getLogger().severe("WorldGuard RegionManager unavailable.");return;}try{ProtectedCuboidRegion r;if(m.hasRegion(LOBBY_REGION_ID)){var old=m.getRegion(LOBBY_REGION_ID);if(!(old instanceof ProtectedCuboidRegion cuboid))throw new IllegalStateException("adminsrv exists but is not a cuboid");r=cuboid;plugin.getLogger().warning("adminsrv exists; retaining bounds.");}else{r=new ProtectedCuboidRegion(LOBBY_REGION_ID,com.sk89q.worldedit.math.BlockVector3.at(Integer.MIN_VALUE,-64,Integer.MIN_VALUE),com.sk89q.worldedit.math.BlockVector3.at(Integer.MAX_VALUE,319,Integer.MAX_VALUE));r.getOwners().addPlayer("ADMINSRV");r.setFlag(Flags.PVP,StateFlag.State.DENY);r.setPriority(1000);m.addRegion(r);}m.save();plugin.getConfig().set("lobby-protection.completed",true);plugin.saveConfig();}catch(Exception e){plugin.getLogger().severe("Failed to protect lobby: "+e.getMessage());}}
 public void refreshIndex(){worldToInstance.clear();try{Map<String,String> map=new HashMap<>();for(String[] i:plugin.db().gameInstances())map.put(i[2],i[0]+"_"+i[1]);for(String[] set:plugin.db().managedWorldSets()){String id=map.get(set[0]);if(id!=null)for(int i=1;i<=4;i++)if(set.length>i&&!set[i].isBlank())worldToInstance.put(set[i],id);}}catch(Exception e){plugin.getLogger().warning("Could not read grief/world-set registry: "+e.getMessage());}}
 public void ensureLobby(){World w=Bukkit.getWorld("lobby");if(w==null){File f=new File(Bukkit.getWorldContainer(),"lobby");if(!new File(f,"level.dat").isFile()){plugin.getLogger().severe("Lobby folder has no level.dat: "+f);return;}try{w=Bukkit.createWorld(new WorldCreator("lobby").environment(World.Environment.NORMAL));}catch(Exception e){plugin.getLogger().severe("Could not load lobby: "+e.getMessage());return;}}if(w!=null){configureLobbyWorld(w);protectLobbyOnce();plugin.getLogger().info("Lobby ready: lobby");}}
 public String instanceOf(String name){return worldToInstance.get(name);}
 public World lobby(){return Bukkit.getWorld("lobby");}
 public boolean modeEnabled(String mode){return plugin.getConfig().getBoolean("game-modes."+mode+".enabled",true);}
  public int count(String mode){if(!modeEnabled(mode))return 0;return switch(mode){case "survival"->Math.max(0,plugin.getConfig().getInt("game-modes.survival.instances",20));case "anarchy"->Math.max(0,plugin.getConfig().getInt("game-modes.anarchy.instances",15));case "hardcore"->Math.max(0,plugin.getConfig().getInt("game-modes.hardcore.instances",5));default->0;};}
 public int capacity(String mode){return Math.max(1,plugin.getConfig().getInt("game-modes."+mode+".capacity","survival".equals(mode)?20:15));}
  public void goInstanceSpawn(Player p){if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return;}if(plugin.inCombat(p.getUniqueId())){p.sendMessage("§cНельзя использовать /spawn в бою.");return;}String id=instanceOf(p.getWorld().getName());if(id==null){p.sendMessage("§cКоманда /spawn доступна только в игровом грифе.");return;}World target=Bukkit.getWorld(id+"_spawn");if(target==null){p.sendMessage("§cМир спавна грифа не загружен.");return;}if(p.teleport(target.getSpawnLocation(),org.bukkit.event.player.PlayerTeleportEvent.TeleportCause.COMMAND)){if(id.startsWith("hardcore_")){p.setGameMode(GameMode.SPECTATOR);}else{p.setGameMode(GameMode.ADVENTURE);configureSpawnPlayer(p);}p.sendMessage("§aВы телепортированы на спавн грифа.");}}
 public boolean goTo(Player p,Location l){if(l==null||l.getWorld()==null)return false;boolean ok=p.teleport(l,PlayerTeleportEvent.TeleportCause.PLUGIN);if(!ok)p.sendMessage("§cНе удалось телепортироваться.");return ok;}
 public int online(String id){int n=0;for(Player p:Bukkit.getOnlinePlayers())if(id.equals(instanceOf(p.getWorld().getName())))n++;return n;}
 public boolean isModeWorld(World w){return w!=null&&instanceOf(w.getName())!=null;}
 public boolean isSpawnWorld(World w){return w!=null&&isModeWorld(w)&&w.getName().endsWith("_spawn");}
 public boolean canSee(Player a,Player b){if(!plugin.authed(a.getUniqueId())||!plugin.authed(b.getUniqueId()))return false;String x=instanceOf(a.getWorld().getName()),y=instanceOf(b.getWorld().getName());return x==null&&y==null||x!=null&&x.equals(y);}
  @EventHandler(priority=EventPriority.MONITOR) public void onPlayerChangedWorldVisibility(PlayerChangedWorldEvent e){Player p=e.getPlayer();Bukkit.getScheduler().runTaskLater(plugin,()->{if(p.isOnline())syncVisibility();},1L);}
 @EventHandler(priority=EventPriority.MONITOR) public void visibilityJoin(PlayerJoinEvent e){Player joined=e.getPlayer();Bukkit.getScheduler().runTaskLater(plugin,()->{if(joined.isOnline())syncVisibility();},5L);}
  @EventHandler(priority=EventPriority.MONITOR) public void visibilityAuth(org.bukkit.event.player.PlayerCommandPreprocessEvent e){String raw=e.getMessage().trim().toLowerCase(Locale.ROOT);if(!raw.startsWith("/l ")&&!raw.startsWith("/login ")&&!raw.startsWith("/auth "))return;Player p=e.getPlayer();Bukkit.getScheduler().runTaskLater(plugin,()->{if(p.isOnline())syncVisibility();},5L);}
  public void syncVisibility(){List<Player> all=new ArrayList<>(Bukkit.getOnlinePlayers());for(Player a:all)for(Player b:all)if(!a.equals(b)){if(plugin.van(b.getUniqueId())||!canSee(a,b))a.hidePlayer(plugin,b);else a.showPlayer(plugin,b);}}
 public void goHub(Player p){goHub(p,null);}
  public void goHub(Player p,Runnable afterArrival){World w=lobby();if(w==null){p.sendMessage("§cЛобби не загружено.");return;}if(goTo(p,lobbySpawn(w))){Bukkit.getScheduler().runTaskLater(plugin,()->{if(p.isOnline()&&isLobbyWorld(p.getWorld())){configureLobbyPlayer(p);giveLobbyCompass(p);if(afterArrival!=null)afterArrival.run();}},2L);syncVisibility();}}
 @EventHandler public void respawn(PlayerRespawnEvent e){World from=e.getPlayer().getWorld();String id=instanceOf(from.getName());if(id!=null){if(!id.startsWith("hardcore_")){World central=Bukkit.getWorld(id+"_spawn");if(central!=null){e.setRespawnLocation(central.getSpawnLocation());Bukkit.getScheduler().runTask(plugin,()->{Player player=e.getPlayer();if(player.isOnline()&&isSpawnWorld(player.getWorld())){if(id.startsWith("hardcore_"))player.setGameMode(GameMode.SPECTATOR);else{player.setGameMode(GameMode.ADVENTURE);configureSpawnPlayer(player);}}});return;}}if(id.startsWith("hardcore_")){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}else{World w=from.getEnvironment()==World.Environment.NORMAL&&from.getName().endsWith("_spawn")?Bukkit.getWorld(id):worldFor(id,from.getEnvironment());if(w!=null){e.setRespawnLocation(w.getSpawnLocation());if(isSpawnWorld(w))Bukkit.getScheduler().runTask(plugin,()->{Player player=e.getPlayer();if(player.isOnline()&&isSpawnWorld(player.getWorld())){player.setGameMode(GameMode.ADVENTURE);configureSpawnPlayer(player);}});}}}else if(!isModeWorld(from)){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}}
 public void configureSpawnWorld(World world){if(!isSpawnWorld(world))return;world.setPVP(false);world.setGameRule(GameRule.DO_MOB_SPAWNING,false);world.setGameRule(GameRule.DO_PATROL_SPAWNING,false);world.setGameRule(GameRule.DO_TRADER_SPAWNING,false);world.setGameRule(GameRule.DO_INSOMNIA,false);world.setGameRule(GameRule.DO_FIRE_TICK,false);world.setGameRule(GameRule.DO_DAYLIGHT_CYCLE,false);world.setGameRule(GameRule.DO_WEATHER_CYCLE,false);world.setGameRule(GameRule.DO_IMMEDIATE_RESPAWN,true);world.setStorm(false);world.setThundering(false);for(Entity entity:world.getEntities())if(entity instanceof LivingEntity&&!(entity instanceof Player))entity.remove();}
  public void configureSpawnWorldOld(World world){if(!isSpawnWorld(world))return;world.setPVP(false);world.setGameRule(GameRule.DO_MOB_SPAWNING,false);world.setGameRule(GameRule.DO_FIRE_TICK,false);world.setGameRule(GameRule.DO_PATROL_SPAWNING,false);world.setGameRule(GameRule.DO_TRADER_SPAWNING,false);world.setGameRule(GameRule.DO_INSOMNIA,false);world.setGameRule(GameRule.DO_IMMEDIATE_RESPAWN,true);for(Entity entity:world.getEntities())if(entity instanceof LivingEntity&&!(entity instanceof Player))entity.remove();}
  private World worldFor(String id,World.Environment env){return Bukkit.getWorld(id+(env==World.Environment.NETHER?"_nether":env==World.Environment.THE_END?"_the_end":""));}
 @EventHandler(priority=EventPriority.MONITOR) public void onDeath(PlayerDeathEvent e){String id=instanceOf(e.getEntity().getWorld().getName());if(id!=null&&id.startsWith("hardcore_")){banHardcore(e.getEntity().getUniqueId(),id);e.getEntity().sendMessage("§cВы погибли. Вход в этот хардкорный гриф заблокирован.");}}
 @EventHandler(priority=EventPriority.HIGHEST) public void spawnRespawnGameMode(PlayerRespawnEvent e){String id=instanceOf(e.getPlayer().getWorld().getName());if(id==null||id.startsWith("hardcore_")||Bukkit.getWorld(id+"_spawn")==null)return;Bukkit.getScheduler().runTask(plugin,()->{Player player=e.getPlayer();if(player.isOnline()&&isSpawnWorld(player.getWorld())){player.setGameMode(GameMode.ADVENTURE);configureSpawnPlayer(player);}});}
  @EventHandler(priority=EventPriority.HIGHEST) public void blockedDeath(PlayerRespawnEvent e){String id=instanceOf(e.getPlayer().getWorld().getName());if(id!=null&&id.startsWith("hardcore_")&&isBanned(e.getPlayer().getUniqueId(),id)){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}}
 private boolean isBanned(UUID id,String instance){try{return plugin.db().hardcoreBanned(id,instance);}catch(Exception e){return true;}}
 public boolean mayTeleport(Player p,Location to){if(to==null)return false;String id=instanceOf(to.getWorld().getName());try{return id==null||!id.startsWith("hardcore_")||!plugin.db().hardcoreBanned(p.getUniqueId(),id);}catch(Exception e){return false;}}
 public void enter(Player p,String mode,int no){if(plugin.inCombat(p.getUniqueId())){p.sendMessage("§cНельзя менять гриф в бою.");return;}if(!isLobby(p.getWorld())||!plugin.authed(p.getUniqueId()))return;if(!modeEnabled(mode)||no<1||no>count(mode)){p.sendMessage("§cЭтот игровой режим отключён или указан неверный гриф.");return;}String id=mode+"_"+no;try{if("hardcore".equals(mode)&&plugin.db().hardcoreBanned(p.getUniqueId(),id)){p.sendMessage("§cВход в этот хардкорный гриф запрещён.");return;}if(plugin.db().instanceNoForSet(id)>0&&online(id)>=capacity(mode)){p.sendMessage("§cЭтот гриф заполнен.");return;}String[] names={id,id+"_nether",id+"_the_end",id+"_spawn"};World.Environment[] envs={World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END,World.Environment.NORMAL};World target=Bukkit.getWorld(names[0]);if(target==null){boolean any=false;for(String n:names)any|=new File(Bukkit.getWorldContainer(),n).exists();if(!any&&plugin.db().instanceNoForSet(id)>0)throw new IllegalStateException("registered grief data is missing; refusing to generate replacement worlds for "+id);if(any){for(int i=0;i<4;i++){File f=new File(Bukkit.getWorldContainer(),names[i]);if(!f.exists())continue;if(!new File(f,"level.dat").isFile())throw new IllegalStateException("existing world lacks level.dat: "+names[i]);if(Bukkit.createWorld(new WorldCreator(names[i]).environment(envs[i]))==null)throw new IllegalStateException("cannot load existing world: "+names[i]);}target=Bukkit.getWorld(names[0]);if(target==null)throw new IllegalStateException("existing overworld missing: "+names[0]);}else{for(int i=0;i<4;i++){if(Bukkit.createWorld(new WorldCreator(names[i]).environment(envs[i]))==null)throw new IllegalStateException("cannot create dimension "+names[i]);}target=Bukkit.getWorld(names[0]);}plugin.db().rememberWorldSet(id,names[0],names[1],names[2],names[3]);plugin.db().registerGameInstance(mode,no,id);refreshIndex();}World spawnWorld=Bukkit.getWorld(names[3]);if(spawnWorld==null){File spawnFolder=new File(Bukkit.getWorldContainer(),names[3]);if(spawnFolder.exists()&&!new File(spawnFolder,"level.dat").isFile())throw new IllegalStateException("existing spawn world lacks level.dat: "+names[3]);SpawnTemplate.install(plugin,names[3],new File(Bukkit.getWorldContainer(),names[3]).toPath());spawnWorld=Bukkit.createWorld(new WorldCreator(names[3]).environment(World.Environment.NORMAL));if(spawnWorld==null)throw new IllegalStateException("cannot create spawn dimension "+names[3]);}plugin.db().rememberWorldSet(id,names[0],names[1],names[2],names[3]);if(plugin.db().instanceNoForSet(id)==0)plugin.db().registerGameInstance(mode,no,id);refreshIndex();spawnWorld.setPVP(false);spawnWorld.setGameRule(GameRule.DO_MOB_SPAWNING,false);spawnWorld.setGameRule(GameRule.DO_FIRE_TICK,false);Location dest=spawnWorld.getSpawnLocation();String[] saved=plugin.savedPosition(p.getUniqueId());if(saved!=null&&id.equals(instanceOf(saved[0]))){World sw=Bukkit.getWorld(saved[0]);if(sw!=null)dest=new Location(sw,Double.parseDouble(saved[1]),Double.parseDouble(saved[2]),Double.parseDouble(saved[3]),Float.parseFloat(saved[4]),Float.parseFloat(saved[5]));}plugin.gameStateManager().beginInstance(p,id);if(goTo(p,dest)){configureSpawnWorld(spawnWorld);configureSpawnPlayer(p);p.setInvulnerable(plugin.afk(p.getUniqueId())||plugin.van(p.getUniqueId()));p.closeInventory();p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.KEY));p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.SELECTOR));p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.SELECTOR));plugin.db().savePosition(p.getUniqueId(),dest.getWorld().getName(),dest.getX(),dest.getY(),dest.getZ(),dest.getYaw(),dest.getPitch());p.sendMessage("§aВы вошли в гриф §e"+id+"§a.");}else plugin.gameStateManager().cancelTransition(p);}catch(Exception e){plugin.gameStateManager().cancelTransition(p);plugin.getLogger().warning("Could not enter grief "+id+": "+e.getMessage());p.sendMessage("§cНе удалось войти в гриф.");}}
 public void banHardcore(UUID id,String instance){try{plugin.db().banHardcore(id,instance);}catch(Exception e){plugin.getLogger().severe("Could not record hardcore death: "+e.getMessage());}}
 public void giveLobbyCompass(Player p){if(compassKey==null)return;ItemStack compass=GameModeCommand.compass(compassKey);for(int slot=0;slot<p.getInventory().getSize();slot++)if(GameModeCommand.isCompass(p.getInventory().getItem(slot),compassKey))return;ItemStack existing=p.getInventory().getItem(0);if(existing==null||existing.getType().isAir()){p.getInventory().setItem(0,compass);return;}for(int slot=1;slot<p.getInventory().getSize();slot++){ItemStack item=p.getInventory().getItem(slot);if(item==null||item.getType().isAir()){p.getInventory().setItem(slot,compass);return;}}p.getInventory().addItem(compass);p.sendMessage("§eИнвентарь заполнен — компас добавлен рядом.");}
 public void sendToLobby(Player p){World w=lobby();if(!p.isOnline()||w==null)return;if(goTo(p,lobbySpawn(w))){configureLobbyPlayer(p);giveLobbyCompass(p);syncVisibility();}}

  @EventHandler(priority=EventPriority.HIGHEST) public void onJoin(PlayerJoinEvent e){Player p=e.getPlayer();World w=lobby();if(w==null){p.kickPlayer("Lobby unavailable.");return;}plugin.gameStateManager().initialize(p,"lobby");Bukkit.getScheduler().runTaskLater(plugin,()->{if(!p.isOnline())return;World currentLobby=lobby();if(currentLobby==null){p.kickPlayer("Lobby unavailable.");return;}if(!isLobby(p.getWorld()))goTo(p,lobbySpawn(currentLobby));configureLobbyPlayer(p);giveLobbyCompass(p);syncVisibility();},2L);}
 @EventHandler(priority=EventPriority.MONITOR) public void saveOnWorldChange(PlayerChangedWorldEvent e){Player p=e.getPlayer();if(isLobbyWorld(p.getWorld()))configureLobbyPlayer(p);else if(isSpawnWorld(p.getWorld())){configureSpawnWorld(p.getWorld());configureSpawnPlayer(p);}else if(isModeWorld(p.getWorld())){p.setGameMode(configuredGameMode(p.getWorld(),GameMode.SURVIVAL));p.setInvulnerable(plugin.afk(p.getUniqueId())||plugin.van(p.getUniqueId()));}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void lobbyVoid(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&isLobbyWorld(p.getWorld())){e.setCancelled(true);p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.teleport(lobbySpawn(p.getWorld()));}}
 @EventHandler(priority=EventPriority.MONITOR) public void lobbyDeath(PlayerDeathEvent e){if(isLobbyWorld(e.getEntity().getWorld()))Bukkit.getScheduler().runTask(plugin,()->{Player p=e.getEntity();if(p.isOnline()){p.spigot().respawn();Bukkit.getScheduler().runTask(plugin,()->{World w=lobby();if(w!=null){p.teleport(lobbySpawn(w));p.setHealth(p.getMaxHealth());configureLobbyPlayer(p);}});}});}
 @EventHandler(priority=EventPriority.MONITOR) public void saveOnQuit(PlayerQuitEvent e){savePosition(e.getPlayer());}
 private void savePosition(Player p){if(!isModeWorld(p.getWorld()))return;Location l=p.getLocation();try{plugin.db().savePosition(p.getUniqueId(),p.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());}catch(Exception e){plugin.getLogger().warning("Cannot save position: "+e.getMessage());}}
 @EventHandler(priority=EventPriority.MONITOR) public void onWorldChange(PlayerChangedWorldEvent e){Player p=e.getPlayer();if(isModeWorld(p.getWorld())){plugin.restore(p);if(isSpawnWorld(p.getWorld()))Bukkit.getScheduler().runTask(plugin,()->{if(p.isOnline()&&isSpawnWorld(p.getWorld()))configureSpawnPlayer(p);});return;}configureLobbyPlayer(p);for(int i=0;i<p.getInventory().getSize();i++)if(GameModeCommand.isCompass(p.getInventory().getItem(i),compassKey))p.getInventory().setItem(i,null);if(GameModeCommand.isCompass(p.getInventory().getItemInOffHand(),compassKey))p.getInventory().setItemInOffHand(null);p.updateInventory();giveLobbyCompass(p);syncVisibility();}
 @EventHandler public void onQuit(PlayerQuitEvent e){Bukkit.getScheduler().runTask(plugin,this::syncVisibility);}
 @EventHandler(priority=EventPriority.HIGHEST) public void mobSpawnProtection(CreatureSpawnEvent e){if(isSpawnWorld(e.getLocation().getWorld())&&!PortalCustomSpawnPermit.isPermitted())e.setCancelled(true);}
 @EventHandler public void spawnProtection(org.bukkit.event.block.BlockPlaceEvent e){if(isSpawnWorld(e.getBlock().getWorld()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void spawnBreakProtection(org.bukkit.event.block.BlockBreakEvent e){if(isSpawnWorld(e.getBlock().getWorld()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void spawnInteractProtection(PlayerInteractEvent e){if(isSpawnWorld(e.getPlayer().getWorld()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void spawnPvp(org.bukkit.event.entity.EntityDamageByEntityEvent e){if(e.getEntity() instanceof Player player&&isSpawnWorld(player.getWorld())&&(e.getDamager() instanceof Player||e.getDamager() instanceof org.bukkit.entity.Projectile projectile&&projectile.getShooter() instanceof Player))e.setCancelled(true);}
 @EventHandler public void lobbyWeather(WeatherChangeEvent e){if((isLobbyWorld(e.getWorld())||isSpawnWorld(e.getWorld()))&&e.toWeatherState())e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void protectSelectorDrop(PlayerDropItemEvent e){if(isLobby(e.getPlayer().getWorld())&&GameModeCommand.isCompass(e.getItemDrop().getItemStack(),compassKey))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void lobbyDamage(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&(isLobbyWorld(p.getWorld())||isSpawnWorld(p.getWorld()))){e.setCancelled(true);p.setHealth(p.getMaxHealth());p.setFireTicks(0);p.setFallDistance(0);}}
 @EventHandler(priority=EventPriority.HIGHEST) public void lobbyGamemode(PlayerGameModeChangeEvent e){World world=e.getPlayer().getWorld();if(!isLobbyWorld(world)&&!isSpawnWorld(world))return;String configured=plugin.getConfig().getString("admin-worlds."+world.getName()+".game-mode");GameMode required=GameMode.ADVENTURE;if(configured!=null)try{required=GameMode.valueOf(configured.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException ignored){}boolean creator=false;try{creator=plugin.db().rank(e.getPlayer().getUniqueId())==Rank.CSRV;}catch(Exception ignored){}if(isSpawnWorld(world)||isLobbyWorld(world)&&!creator&&e.getNewGameMode()!=required){e.setCancelled(true);e.getPlayer().sendMessage("§cВ этом мире доступен только режим "+required.name()+".");}}
 @EventHandler public void lobbyTick(PlayerMoveEvent e){if(isLobbyWorld(e.getPlayer().getWorld())){configureLobbyPlayer(e.getPlayer());if(e.getTo()!=null&&e.getTo().getY()<-60)e.getPlayer().teleport(lobbySpawn(e.getPlayer().getWorld()));}else if(isSpawnWorld(e.getPlayer().getWorld()))configureSpawnPlayer(e.getPlayer());}
 @EventHandler public void menuGuard(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||isModeWorld(p.getWorld()))return;if(e.getCurrentItem()!=null&&GameModeCommand.isCompass(e.getCurrentItem(),compassKey))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void linkedPortals(PlayerPortalEvent e){World from=e.getFrom().getWorld();String id=instanceOf(from.getName());if(id==null||e.getTo()==null)return;World.Environment env=from.getEnvironment();if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL){World w=env==World.Environment.NORMAL?(from.getName().endsWith("_spawn")?Bukkit.getWorld(id):Bukkit.getWorld(id+"_nether")):env==World.Environment.NETHER?Bukkit.getWorld(id):null;if(w!=null)e.setTo(new Location(w,e.getTo().getX(),e.getTo().getY(),e.getTo().getZ(),e.getTo().getYaw(),e.getTo().getPitch()));}else if(e.getCause()==PlayerTeleportEvent.TeleportCause.END_PORTAL){World w=env==World.Environment.THE_END?Bukkit.getWorld(id):from.getName().endsWith("_spawn")?Bukkit.getWorld(id):Bukkit.getWorld(id+"_the_end");if(w!=null)e.setTo(new Location(w,e.getTo().getX(),e.getTo().getY(),e.getTo().getZ(),e.getTo().getYaw(),e.getTo().getPitch()));}}
}
